// Source -> paragraph of https://5e24srd.com (SRD 5.2.1 as HTML, CC-BY-4.0). The map src/data/srd/links.json is
// generated by tools/build_srd_links.py from the headings of the site: { "<source.section>": "<page>#<anchor>" },
// plus "<section> > <entry name>" for entries whose section is only a chapter ("Spells > Fireball") and
// "p. <page>" for entries without a section.
import type { Source } from './types'
import links from './srd/links.json'

export const SRD_SITE = 'https://5e24srd.com/'
const LINKS = links as Record<string, string>

/** Relative URL on 5e24srd.com of the paragraph a source cites, or undefined when the site doesn't cover it
 * (monsters, animals). `name` is the English name of the entry the source belongs to (the popup title). */
export function srdPath(source: Source | undefined, name?: string): string | undefined {
  if (!source) return undefined
  const sec = source.section
  if (sec) {
    if (name && !sec.includes(' > ')) {
      const byName = LINKS[`${sec} > ${name}`]
      if (byName) return byName
    }
    if (LINKS[sec]) return LINKS[sec]
  }
  return source.page ? LINKS[`p. ${source.page}`] : undefined
}

/** Absolute URL of that paragraph; the site's home page when unknown. */
/** The official SRD 5.2.1 PDFs on D&D Beyond (CC-BY-4.0), opened at a page with `#page=N`. */
const PDF = 'https://media.dndbeyond.com/compendium-images/srd/5.2/'
export const pdfUrl = (lang: 'en' | 'fr' | 'es', page: number) =>
  `${PDF}${lang === 'en' ? '' : lang === 'fr' ? 'FR_' : 'SP_'}SRD_CC_v5.2.1.pdf#page=${page}`

/** The 5e24srd.com paragraph, else the official English PDF at the cited page (the site lacks the Rules Glossary, the
 * magic-item catalog and the monsters), else the site's home page. */
export function srdUrl(source: Source | undefined, name?: string): string {
  const path = srdPath(source, name)
  if (path && path !== 'index.html') return SRD_SITE + path
  if (source?.page) return pdfUrl('en', source.page)
  return SRD_SITE + 'index.html'
}
